import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"漢上易傳卷八","description":"漢上易傳 - 漢上易傳卷八","frontmatter":{"title":"漢上易傳卷八","description":"漢上易傳 - 漢上易傳卷八"},"headers":[],"relativePath":"classics/hanshang/009.md","filePath":"classics/hanshang/009.md"}'),n={name:"classics/hanshang/009.md"};function r(c,p,_,i,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="漢上易傳卷八" tabindex="-1">漢上易傳卷八 <a class="header-anchor" href="#漢上易傳卷八" aria-label="Permalink to “漢上易傳卷八”">​</a></h1><p>翰林學士、左朝奉大夫知制誥兼侍讀、兼資善堂翊善、長林縣開國男食邑三佰戶。賜紫金魚袋。朱震集傅。 八卦成列，象在其中矣；因而重之，爻在其中矣。剛柔相推，變在其中矣。繫辭焉而命之，動在其中矣。吉凶悔吝者，生乎動者也；剛柔者，立本者也；變通者，趣時者也；吉凶者，貞勝者也。天地之道，貞觀者也；日月之道，貞明者也。天下之動，貞夫一者也。大乾確然示人易矣；夫坤，隤然示人簡矣。爻也者，效此者也。象也者，像此者也。爻象動乎內，吉凶見乎外，功業見乎變，聖人之情見乎辭。伏羲始晝八卦，八卦成列，而乾坤定位。震巽一交也，坎離艮兌二交也。兌以一陽與艮，坎以一陰奉離，震巽以二相易，六十四卦之象在其中矣。三晝，天地人也。伏羲因而重之，六位成章，兼三才而兩之，則三百八十四爻在其中矣。歸藏初經八卦六爻，則知因而重之者伏羲也。姚信曰：連山氏得河圖，夏人因之曰連山。歸藏氏得河圖，摘人因之曰歸藏。伏羲氏得河圖，周人因之曰周易。連山，神農氏也。歸藏，黃帝氏也。其經卦皆八，本伏羲也。其別卦皆六十有四，因八卦也。六爻剛柔互相推蕩，六十四卦之變在其中矣。鄭康成曰：虙羲作十言之教，曰：乾、坤、震、巽、坎、離、艮、兌、消息無文字謂之易。乃知周易繫辭於卦下者，文王也。文王繫辭，指其象而命之以名，則周公之爻辭所以鼓天下之動者在其中矣。彖辭曰吉凶而巳。吉凶悔吝者，爻辭也。是亦生乎卦之動也。爻動靜當則吉，當靜而動，當動而靜，則兇悔吝矣。言吉凶悔吝生乎動者，主動爻言之也。自神農氏而下，演為三易，贊為十翼，非聖人能為是也。引而伸之，不外是也。爻有剛柔，不有兩則一不立，所以立本也。剛柔相變，通其變以盡利者，趣時也。趣時者，時中也。故曰：乾坤毀，則無以見易矣。剛柔相錯，有當有否，則吉凶生。又曰：吉凶者，貞勝也。何謂邪？此於動中明乎不動者也。韓康伯謂不累乎吉凶是巳。張載曰：有義命當吉當兇、當否當亨者，聖人不使避兇趣吉，一以貞勝而不顧。如大人否亨，有隕自天，過涉減頂，兇無咎。損益龜不克違，及其命亂也之類。天地之道有升降，然上下之觀不動也。故曰天地之道貞觀也。日月之道有往來，然晝夜之明不動也，故曰日月之道貞明也。天下之動，吉凶之變多矣，而君子安其義命，一以貞勝，吉凶不能動，何累之有？故曰天下之動，貞夫一也。一者，貞也。貞所以一天下之動，此彖辭、爻辭所以貴夫貞也。吉凶以貞勝，故能立天下之本，趣天下之時。八卦本乾坤者也。夫乾陽至剛，確然不易，示人為君為父為夫之道，不亦易乎。夫坤陰至柔，隤然而順，示人為子為臣為婦之道，不亦簡乎？乾剛坤柔，以立本者也。爻也者，效乾坤之動者也。天道下濟，地道上行，剛柔相推，變通以趣時者也。象者，像乾坤之象者也。爻有變動，象亦像之。爻象動乎內者，有當有否，則人事之見於外者，有吉有兇。人與乾坤一也。吉凶之變，有術通之，兇者反之，吉則功業不期於見而見矣。觀此，則乾坤示人足矣。聖人必以彖言乎象，爻言乎變。繫辭以言吉凶者，聖人之情，愛人無巳也。恐其陷於兇咎，是以指其所之，故考乎其辭，則聖人之情見矣。</p><p>天地之大德曰生，聖人之大寶曰位。何以守位曰仁，何以聚人曰財，理財正辭，禁民為非曰義。古者包犧氏之王天下也，仰則觀象於天，俯則觀法於地，觀鳥獸之文與地之宜，近取諸身，遠取諸物，於是始作八卦，以通神明之德，以類萬物之情。作結繩而為罔罟，以佃以漁，蓋取諸離。包犧氏沒，神農氏作，斲木為耜，揉木為耒，耒耨之利以教天下，蓋取諸益。日中為市，致天下之民，聚天下之貨，交易而退，各得其所，蓋取諸噬嗑。神農氏沒，黃帝堯舜氏作，通其變，使民不倦，神而化之，使民宜之。易窮則變，變則通，通則久，是以自天祐之，吉無不利。黃帝堯舜垂衣裳而天下治，蓋取諸乾坤。刳木為舟，剡木為楫，舟楫之利，以濟不通，致遠以利天下，蓋取諸渙。服牛乘馬，引重致遠，以利天下，蓋取諸隨。重門擊柝，以待暴客，蓋取諸豫。斷木為杵，掘地為臼，臼杵之利，萬民以濟，蓋取諸小過。弦木為弧，剡木為矢，弧矢之利，以威天下，蓋取諸睽。上古穴居而野處，後世，聖人易之以宮室，上棟下宇，以待風雨，蓋取諸大壯。古之葬者，厚衣之以薪，葬之中野，不卦不樹，喪期無數，後世。聖人易之以棺槨，蓋取諸大過。上古結繩而治，後世。聖人易之以書契，百官以治，萬民以察，蓋取諸夬。是故易者，象也。象也者，像也。彖者，材也。爻也者，效天下之動者也。是故吉凶生而悔吝著也。</p><p>胡旦分天地之大德曰生為一章，陽卦多陰為一章，考之文義，當從旦。龔原本亦然。乾，大生也。坤，廣生也。乾坤合而成德，生物而巳，故曰</p><p>天地之大德曰生。聖人之情見乎辭者，亦天地之德也。聖人成位乎兩間，有其德無其位，不能兼善天下。於其位也，慎之重之，在卦則尊位也。故曰聖人之大寶曰位。天地之大德曰生者，仁也。聖人成位乎兩間者，仁而巳矣。不仁不足以參天地聖人者，聰明睿知神武而不殺，不殺者，好生也。故曰何以守位曰仁，仁被萬物，取財於天地，則財不可勝用其民，養生喪死無憾，可以保四海，守宗廟社稷，故曰何以聚人。曰財。理財者，節之以制度也，節之類是也。正辭者，正邪說也，六辭是也。禁民為非者，禁其非，歸之於是也。如是乃得其宜，故曰義。義所以為仁，非二本也。故曰立人之道，仁與義莫非義也。義至於禁民為非，盡矣。自此以下，明備物致用，立成器以為天下利者，無非有取於易，皆仁也。曰王天下者，明守位也。所謂崇高，莫大乎富貴也。鳥獸之文即天文。太玄曰：察龍虎之文，觀鳥龜之理，舉鳥獸則龜見矣。仰觀龍虎鳥龜之文，其形成於地。俯觀山川原隰之宜，其象見於天。凡在地者，皆法天者也。近取諸身，則八卦具於百骸，而身無非物。遠取諸物，則八卦具於萬物，而物無非我。故神明之德雖異而可通，萬物之情雖眾而可類，其道至於一以貫之，此包犧氏所以作易。一者何？仁也。上古茹毛飲血，故教之以佃魚，蓋取諸重離巽繩，離目罔目謂之罟，兩目相連結繩為之。罔，罟也。離，雉佃也。兌巽為魚，漁也。觀此則伏犧畫八卦，因而重之明矣。神農氏時，民厭鮮食，而食草木之實，聖人因是以達其不忍之心，故教以耒耜之利，蓋取諸益。益，否，乾之初也。乾金斲巽木，斲木也。四之三成坎，坎為揉木，初成震，揉木也。入坤土而巽於前，斲木為耜也。動於後，揉木為耒也。耒耜之利，其益無方矣。是時民甘其食，美其服，至死不相往來，故教之以交易，蓋取諸噬嗑。噬嗑，否五之初也。離日在上為日中，坤眾在下為市眾，為民。離有伏兌為蠃貝。坤往之乾，致天下之民，聚天下之貨也。以坤交乾，交易也。乾五退初而得位，各得其所也。佃漁不言利於耒耜，言利佃漁，非聖人本心也。佃有猛虎之害，漁有蛟龍之害，不若耒耜之利。為市不言利者，聚天下之貨，利在其中矣。唐虞氏時，洪水之患，庶民鮮食，然後教民稼穡，懋遷有無，化居其道，萬世一揆。神農氏沒，民情巳厭。黃帝堯舜作，因其可變，變而通之，使民日用其道而不倦，而又微妙入神，化而無跡，天下各得其宜。蓋易道陽極變陰，陰極變陽，變則不窮，不窮則可久而不息，善乎變通以趣時也。是以自天祐之，吉無不利，聖人先後天故也。神農氏時，與民並耕而食，饔飧而治，正是尊卑定位，君逸臣勞，乾坤無為，六子自用，垂衣裳而天下治，蓋取諸乾坤。乾在上為衣，坤在下為裳。上古山無蹊，澤無樑，至是舟楫之利，以濟不通，蓋取渙。渙，否四之二也。乾金刳巽木浮於坎上，刳木為舟也。離火上銳，剡木為楫也。否塞者，渙散濟不通也。上古牛未穿，馬未絡，至是服牛乘馬，引重致遠，以利天下，蓋取諸隨。隨，否上九之初也。坤牛而震足驅之，服牛也。震作足馬，而巽股據之，乘馬也。坤輿震輹，上六引之，引重也。內卦近外卦遠，上六在外卦之外，致遠也。牛馬隨人而動，否不通也。上之初，濟不通也。上古外戶不閉，御風氣而巳，至是重門擊柝，以待暴客，蓋取諸豫。豫，謙之反也。謙艮為門，九三之四又為門，重門也。艮為手，坎為堅木，震為聲，手擊堅木而有聲，擊柝也。坤為闔戶，而坎盜逼之，暴客也。知耒耜而不知杵臼之利，則利天下者有未盡，故教之以杵臼之利，蓋取諸小過。小過，明夷，初之四也。兌金斷巽木，斷木為杵也。巽木入坤土，掘地為臼也。坎，陷也。曰之象，杵動於上，臼止於下，四應初，三應上，上下相應，杵臼之利也。坎變巽股，萬民濟也。知門柝而不知弧矢之利，則威天下者有未盡，故教之以弧矢之利，蓋取諸睽。睽，家人反也。家人巽為木，巽離為絲，坎為弓，弦木為弓也。兌金剡木而銳之，剡木為矢也。兌決乾剛，鹹天下也。聖人以百姓心為心，民之所欲，不以強去；民之所惡，不以強留。然變而通之者，亦因其典禮以損益之而已。且上古穴居而野處，後世聖人易之以宮室。自黃帝而來、夏后氏之世室、商人之重屋、周人之明堂。宮室之制有不同。而上棟下宇、以待風雨、取諸大壯者同也。大壯自遁來、三複三變也。一變中孚、艮為居、兌為口、穴之象。穴居也。再變大畜、乾在上、天際也。野之象。巽入變艮而止，野處也。三變大壯，震木在上，棟也。乾天在下，宇也。巽風隱，兌澤流，待風雨也。大壯則不撓矣。古之葬者，厚衣之以薪，葬之中野，不封不樹，喪期無數。後世，聖人易之以棺槨。自堯舜以來，有虞氏之瓦棺，夏后氏之垐周，商人之梓，棺槨之制，有不同，而取諸大過者同也。大過自遁四變，一變訟，乾見坤，隱不封也。再變巽木而兌金，毀之不樹也。三變鼎，離為目，兌澤流喪也。上九變而應三，坎兌為節，不變，喪期無數也。木在澤下，中有乾人，棺槨也。葬則棺周於身，槨周於棺，土周於槨，大過也。上古結繩而治後世，聖人易之以書契。象形、會意、轉註、處事、假借、諧聲。書契之制有不同，而百官以治，萬民以察。取諸夬者，同也。夬自姤五變，一變同人，二變履，三變小畜，四變大有。姤巽為繩，結繩也。巽變成離，坤離為文書也。兌金刻木契也。乾為君，坤為臣民。坤居二四上，百官以治也。離明上達，萬民以察也。以是決天下疑者，夬也。以是推之，後世畋獵捕魚之器雖不同，而取於離則同也。井收溝洫之事雖不同，而取於益則同也。胡中夕市雖不同，而取於噬嗑則同也。餘卦可以類推矣。蓋動於人情，見於風氣，有是時必有是象。易者，象也。易之有象，擬諸其形容而巳，猶繪畫之事，雕刻之工，一毫損益則不相似矣。象之辭又謂之彖者，言乎其才也。卦有剛柔，才也。有是時，有是象，必有是才以濟人，才與時會，斯足以成務矣。然天下之動，其微難知，有同是一時，同處一事，所當之位有不同焉，則趨舍進退殊途矣。故曰：爻者，效天下之動也。是以卦同爻異，趣時之變不得而同，然所歸則若合符節。故自伏犧、神農、黃帝堯舜凡六萬一千四百有餘歲而行十卦而巳。夫爻動則有吉凶悔吝，吉凶者，所以生大業也。吉凶生而悔吝著，其動可不慎乎？</p><p>陽卦多陰，陰卦多陽，其故何也？陽卦奇，陰卦耦，其德行何也？陽一君而二民，君子之道也。陰二君而一民，小人之道也。易曰：憧憧往來，朋從爾思。子曰：天下何思何慮？天下同歸而殊塗，一致而百慮。天下何思何慮？日往則月來，月往則日來，日月相推而明生焉。寒往則暑來，暑往則寒來，寒暑相推而歲成焉。往者，屈也；來者，信也。屈信相感而利生焉。尺蠖之屈，以求信也。龍蛇之蟄，以存身也。精義入神，以致用也。利用安身，以崇德也。過此以往，未之或知也。窮神知化，德之盛也。易曰：困於石，據於蒺䔧，入於其宮，不見其妻㓙。子曰：非所困而困焉，名必辱；非所據而據焉，身必危。既辱且危，死期將至，妻其可得見邪？易曰：公用射隼於高墉之上，獲之，無不利。子曰：隼者，禽也，弓矢者，器也；射之者，人也。君子藏器於身，待時而動，何不利之有？動而不括，是以出而有獲，語成器而動者也。子曰：小人不恥不仁，不畏不義，不見利不勸，不威不懲。小懲而大誡，此小人之福也。易曰：屨校滅趾，無咎。此之謂也。善不積不足以成名，惡不積不足以滅身。小人以小善為無益而弗為也，以小惡為無傷而弗去也，故惡積而不可揜，罪大而不可解。易曰：何校滅耳。兇子曰：危者，安其位者也；亡者，保其存者也；亂者，有其治者也。是故君子安而不忘危，存而不忘亡，治而不忘亂，是以身安而國家可保也。易曰：其亡其亡，繫於苞桑。子曰：德薄而位尊，知小而謀大，力少而任重，鮮不及矣。易曰：鼎折足，覆公餗，其形渥，兇。言不勝其任也。子曰：知幾其神乎！君子上交不謟，下交不瀆，其知幾乎！幾者，動之微，吉之先見者也。君子見幾而作，不俟終日。易曰：介於石，不終日，貞吉。介如石焉，寧用終日，斷可識矣。君子知微知彰，知柔知剛，萬夫之望。子曰：顏氏之子，其殆庶幾乎！有不善，未嘗不知，知之未嘗復行也。易曰：不遠復，無祗悔，元吉。天地絪縕，萬物化醇，男女構精，萬物化生。易曰：三人行則損一人，一人行則得其友。言致一也。子曰：君子安其身而後動，易其心而後語，定其交而後求。君子修此三者，故全也。危以動，則民不與也；懼以語，則民不應也。無交而求，則民不與也。莫之與，則傷之者至矣。易曰：莫益之，或擊之，立心勿恆，兇。</p><p>凡得乎乾者為陽卦，震、坎、艮是也。凡得乎坤者為陰卦，巽、離、兌是也。陽卦以奇為本，故多陰。陰卦以耦為本，故多陽。本不可二也。陰陽二卦，其德行不同，何也？陽一君而徧體二民，二民共事一君，一也，故為君子之道。陰卦一民共事二君，二君共爭一民，二也，故為小人之道。陽貴陰賤，晝人多福，夜人多禍，故君子貴夫一也。鹹九四曰：憧憧往來，朋從爾思者，勞神明以為一也。夫思之所及，朋則從之，思之所不及，其誰從乎？雖憧憧於往來之間，其從亦狹矣，不知天下何思何慮，萬物即一，一即萬物，同歸而有殊塗，一致而具百慮，其一既通，萬物自應，豈思慮營營之所至哉。且日月寒暑，一往一來，自異者觀之，兩也。相推而生明，相推而成歲，自同者觀之，一也。自往自來，其誰使之？往者，屈也，來者，信也。一屈一信，默然相感而利生焉。尺蠖不屈則不能信，龍蛇不蟄則不能存。消息循環，相待而為用。夫致用在於精義，義則無決擇，無取捨，唯其宜而巳。精一於義，則進而入於不可知之神，故感而後動。其動也天，其用利矣。遊乎人間，物莫之傷，其身安矣。利用安身，日進無疆，德不期於崇而自崇矣。此吾之所知也。過此以往則化矣。如日月有明，容光必照，寒暑相代，萬物自生，日月寒暑所不能知也。故曰，聖人有所不知焉，聖人有所不能焉。然則所謂化者，終不可知歟？曰：窮神之所為，則知化矣，德盛者自至焉。道至於此，萬物與我一也。故曰一則神，兩則化。窮神則知變化之道。人孰不欲安其身？或困於石而不知休，據於蒺䔧而不知避，名既汙辱，身既危殆，日近於死亡，雖欲安得乎哉？妻且不得見也，況朋從乎？藏可用之器，待可為之時，動無結閡，出則有獲，唯乘屈信之理，而其用利者能之。小人不恥不仁，故不畏不義，陷於死亡，辱及其先，恥孰大焉？雖愚也，而就利避害與人同，故見利而後勸，威之而後懲。小懲大誡，猶為小人之福，況真知義乎？精於義者，豈一日積哉。彼積不善以滅其身者，不知小善者，大善之積也。夫身者，國家之本，存亡治亂之所繫，身雖安矣，猶不可恃也。故安其位者危，保其存者亡，有其治者亂。君子兢兢業業，不恃其有，故身安而國家可保，國家保而德崇矣。位欲當德，謀欲量知，任欲稱力，三者各當其實，則用利而身安。小人志在於得而巳，以人之國，僥倖萬一，鮮不及禍。自古一敗塗地，殺身不足以塞其責者，本於不知義而己。神難言也。精義入神以致用，其唯知幾乎。知幾其神矣。幾者，動之微，吉之先見。譬如陽生而井溫，雨降而云出，眾人不識，而君子見之，其於行義也，不亦有餘裕乎？夫安危存亡之幾，在於始交之際。君子上交不謟，下交不瀆，義之與比，無悔吝藏於其中，知幾故也。是以君子見微已去，小人遇禍不知。見與不見，相去遠矣。進此道者，存乎介而已。確然守正，不轉如石者，乃能見之，其心定，其智明，默識而善斷，故不俟終日也。守身如此，無一朝之患矣。知彰易，知微難，知剛易，知柔而剛難，君子見幾。故知微知彰，知柔知剛，一龍一蛇，或弛或張，唯義是適，則萬夫望之而取法焉。所從者豈特其朋從之，彼勞思慮者亦末矣。夫智周萬物者，或暗於自知；雄入九軍者，或憚於改過，克已為難也。顏子有不善未嘗不知，知之未嘗復行，故曰顏氏之子，其殆庶幾乎。孰謂小善為無益而可以弗為，小惡為無傷而可以弗去乎？復者，剛反動之卦也。善者，天地之性而人得之，性之本也。不善非性也，習也。不遠而復者，修為之功也。故曰：不善未嘗弗知，知之未嘗復行。知之者，覺也，自性也。或曰：鮒椒之惡，豈習乎？曰：知修為之功，則復其本矣。由其習之不巳，迷而不復矣。人之生，有氣之質，有性之本。剛柔不齊者，氣也，性之本則一而巳矣。故曰：天地貞，觀也，日月貞，明也。氣豈能變哉？天地萬物，其本一也。天地升降，其氣絪縕，萬物化矣，醇而未雜。序卦曰：</p><p>有天地，然後有萬物。劉牧曰：乾道自然而成男，坤道自然而成女。序卦言萬物，則男女在其中矣。曰萬物化醇者，言其一未始離也。天地既生萬物，萬物各有陰陽，精氣相交，化生無窮。序卦曰：有萬物，然後有男女。劉牧曰：鹹卦不繫之於離坎，以離坎而上，男女自然而生。鹹卦而下，男女偶合而生。曰男女，曰化生者，言有兩則有一也。損之</p><p>六三曰：三人行則損一人，一人行，則得其友。言致一也。致一則殊塗而同歸，一致而百慮矣。老氏論天地王侯得一，又曰：天地相合而降甘露。老氏之所謂得一相合，即夫子所謂致一也。其在卦則六爻相應，合而致用是也。所謂全者，合我與人而為一也。動而與之者，安其身而後動也。語之而應者，平其心而後慮也。求而與之者，定其交而後求也。三者得，故能以天下為一家，中國為一人，故曰君子修此三者，故全也。離而為二，物物成敵，莫或與之，擊之者至矣。故曰立心勿恆兇。勿恆者，不一之謂也。張載曰：下文當雲：易曰：自天祐之，吉無不利。子曰：天之所助者順也，人之所助者信也。履信思乎順，又以尚賢也。是以自天祐之，吉無不利也。考之義或然也。順乎天者天助之，應乎人者人助之，致一之效乎。此章以鹹、困解噬嗑、否、鼎、復、損、恆九卦十爻盡其意，蓋書之於言有不能盡也。</p><p>子曰：</p><p>乾坤，其易之門邪！乾，陽物也。坤，陰物也。陰陽合德，而剛柔有體，以體天地之撰，以通神明之德。其稱名也，雜而不越，於稽其類其衰世之意邪！夫易彰往而察來，而微顯闡幽，開而當名辨物，正言斷辭，則備矣。其稱名也小，其取類也大，其旨遠，其辭文，其言曲而中，其事肆而隱，因貳以濟民行，以明失得之報。</p><p>乾坤其易之門邪！乾坤毀，則易無自而入矣。乾剛者，陽之物，老陽之策也，其德則健。坤柔者，陰之物，老陰之策也，其德則順。陰陽，氣也；剛柔，形也。氣變而有形，形具而有體。是故總策成爻，健順合德，而剛柔之體見矣。聖人以此體天地之撰。體，形容之也。撰，定也。形容天地之所定者，體造物也，即剛柔有體是已。天，神也。地，明也。通神明之德者，示幽顯一源也，即陰陽合德是巳。陰陽相蕩，剛柔相推，自乾坤而變八卦，自八卦而變六十四卦。三百八十四爻。其稱名也。雜然不齊。枝葉至扶疏矣。而亦不越乎陰陽二端而巳。乾坤其易之門邪。伏羲始畫八卦。文王監於二代而作周易。周公因於文王而作爻辭。卦有象。爻有變動。繫辭焉而命之日益詳矣。蓋時有隆汙。道有升降。世既下衰，不如是不足以盡天下之情偽。何以知其然哉。於此稽考其類。則知之矣。夫易之為書，以八卦言之。自震至乾，彰往也。自巽至坤，察來也。一往一來，周旋無窮，是謂環中。以重卦言之，前卦為往，後卦為來。自內之外為往，自外之內為來。彰往故微顯，察來故闡幽。顯莫如既往而有微而難知之理。幽莫如方來而有顯而易見之象。開釋爻卦，各當其名，無隱也。辨陰陽之物，正吉凶之辭，無遺也。斷之以卦辭爻辭，則備矣。觀乎此宜，若坦然明白，使人易曉矣。然而其稱名也小，則百物不廢；其取類也大，則達之於天下。意有餘，故其旨遠；物相雜，故其辭文，其言致曲而後中於道，其事閎肆，其實本於隱，非天下至神至精至變，有不能與也。而又因其疑貳不決、恐懼易入之時，以濟民行，告之以吉凶悔吝之辭，以明失得之必報。蓋有遠害防患之心，非衰世之意乎？</p><p>易之興也，其於中古乎？作易者，其有憂患乎？是故履，德之基也；謙，德之柄也；復，德之本也；恆，德之固也。損，德之修也。益，德之裕也。困，德之辯也。井，德之地也。巽，德之制也。履，和而至。謙，尊而光。復，小而辯。於物。恆，雜而不厭。損，先難而後易。益，長裕而不設。困，窮而通。井，居其所而遷。巽，稱而隱。履以和行，謙以制禮，復以自知，恆以一德，損以遠害，益以興利，困以寡怨，井以辯義，巽以行權。作易者，上古也；興易者，中古也。何以知易興於中古邪？觀九卦之象，聖人有憂患後世之心，得失滋彰矣。然則上古作易，何以知有憂患乎？曰：聖人隨時者也。佃魚不厭，則耒耜之利不興；結繩未弊，則書契之文不作。而所以憂患後世者，固已具於八卦之中，至於文王而易道興矣。履說而應乎乾，履乎和者也，故為德之基。謙，執之而有終者也，故為德之柄。復，剛反動而復其初，德自此始者也，故為德之本。恆，久而不已，終則有始者也，故為德之固。損，損其可損而致一者也，故為德之修。益，益其可益而日進者也，故為德之裕。困，剛見揜而不失其所亨者也，故為德之辨。井，剛中而不變者也，故為德之地。巽以剛下柔，不失乎中者也，故為德之制。復和而至於禮，不至則流而徇於物矣。謙卑而人尊之，其道光也。復小而辨於物者，以初九也。人之所以異於萬物者，以其存心也。剝之剛陽反動於初，則善心生於冥昧難知之時，不俟乎大而後與物辨也。斯非德之本歟？恆，泰之變也。初九正也，動而之三，雷風並作，萬物繁興之時。三守正不動，酬酢而不厭，天地所不能旋，日月所不能眩，可以言德之固矣。損先難而後易，何也？情慾者，強陽之氣也，初損之必有吝心，剛健決斷，乃能行之，故先難也。及其既損，考諸理而順，反諸心而悅，其孰御我哉？故後易也。夫一介不以取諸人，然後系千駟之馬而弗視，祿之以天下而弗顧，故曰仁亦在熟之而巳。益長裕而不設，何也？益，否之變也。九四，下益於初，初，九正也，益物以誠也。益物以誠，即是自益以誠，故四與初以益，而正誠自成也。受益者不贅，益之者不虧，與時偕行，如天地之裕萬物，非張設之也。困窮而通，何也？否之上九，陷而之二，上下柔，揜之窮也。處險而說，在窮而心亨，通也。通者，不窮之謂，豈必富貴利達而後為通哉。故曰學不能行謂之病，病則窮矣。井居其所而遷，何也？泰初之五為井，初九正也，九五亦正也。初遷之五，往者正也。五遷之初來者正也。五居其所而往來皆正能遷也。巽稱而隱，何也？臨二之四為巽稱者，輕重均之謂也。二陰方進，六二從四，九四君子屈巳以下之，則君子小人勢均矣。人見其屈已以為巽，而不知六二亦巽乎剛，故曰稱而隱。履以和行，何也？和者禮之用，節者禮之體，節而不和，禮不行矣。謙以制禮，何也？禮自卑而尊，人自後而先人不能乎謙，安能行禮？復以自知，何也？有善必自知之，不善必自知之。修其善，去其不善，則復矣。恆以一德，何也？雜而不厭，非徇物也，久而不變也。久則其德無二三矣。損以遠害，何也？自損以修德，則物無害之者。故曰恭寡過，情可信，儉易容也。以此失之者鮮矣。益以興利，何也？因其所利而利之也。困以寡怨，何也？雖困而通，在窮而悅，樂天者也。我不尤人，人復何怨。井以辨義，何也？井自守以正，與人必以正，處己處人，各得其宜者也。巽以行權，何也？權者，稱之所以輕重也。與時推移，湣然無際，如行權稱物，人見其適平而巳。其序則履和執謙，複本恆久，損巳益人，然後可以處困。不窮能遷，然後可以行權。九卦，履出於乾，謙、復出於坤，恆出於震，損出於艮，益出於巽，困、井出於坎，獨不取離可也。離，萬物皆相見之卦，包犧氏取之文王，內文明，外柔順，以蒙大難，明在地中時也。</p><p>易之為書也，不可遠，為道也屢遷，變動不居，周流六虛，上下無常，剛柔相易，不可為典要，唯變所適。其出入以度內外，使知懼，又明於憂患與故，無有師保，如臨父母。初率其辭而揆其方，既有典常，苟非其人，道不虛行。龔原曰：易之為書也三章。當從龔。此章言易有變動出入。易之為書，明天地之用，其用不過乎六爻，不可遠也。遠此而求之，則違道遠矣。其道也屢遷，有變有動，不居其所，升降往來，循環流轉於六位之中。位謂之虛者，虛其位以待變動也。故太玄九位亦曰九虛。或自上而降，或自下而升，上下無常也。剛來則柔往，柔來則剛往，剛柔相易也。無常則不可為典，相易則不可為要。流行散徙，唯變所適。然亦不過乎六爻。不過者，以不可遠也。其出入雲者，以一卦內外言之，兩體也。出者，自內之外往也。入者，自外之內來也。以是度外內之際，而觀消息盈虛之變，出處進退之理，使知戒懼。當出而入，與當入而出，其患一也。故大觀在上，窺觀者醜，三陽方壯，牽羊悔亡。出入內外，本於相形。此四從二亦曰外，離五用九亦曰出，唯精於義者能知之。知義則知懼矣。又此書明於巳之所當憂患，與所以致憂患之故，安不忘危，存不忘亡，治不志亂，無有師保教訓而嚴憚之，明失得之報也。如有父母親臨而愛敬之，見聖人之情也。初率其吉凶之辭，揆其八卦之方，則既有典常可守矣。蓋不可遠者，易之體也，而有用焉。為道也屢遷者，易之用也，而有體焉。能知卦象合一，體用同源者乎？斯可以言易之書矣。書，載道者也，待人而後行，苟非其人，道不徒行。</p><p>易之為書也，原始要終，以為質也。六爻相雜，唯其時物也。其初難知，其上易知，本末也。初辭擬之，卒成之終。若夫雜物撰德、辨是與非、則非其中爻不備。噫亦要存亡吉凶、則居可知矣。知者觀其彖辭、則思過半矣。</p><p>此章言重卦六爻之義。易之為書也、原始於初爻、要終於上爻、成六位以為體質者也。八卦，八物也。六爻，六時也。六爻相雜、時異而物異。八卦，本象也。時物，別象也。其本甚微，故難知；其末巳著，故易知。初辭擬而後言，不亦難知乎？卒成之，其事終矣，不亦易知乎？上下之位，以時言之，初終也。以道言之，本末也。以事言之，始卒也，其實一也。時變則事變，事變則道與之俱，未有違時造事而能成者。三畫非無本末也，聖人何為重卦？曰，理具乎中，其事則未也。若夫糅雜八卦之物，撰定六爻之德，辨得失是非，則非中爻不備中爻，崔憬所謂二三四五，京房所謂玄體是也。蓋物無常是，亦無常非，施於彼者或不可施於此，用於古者或不可行於今。蒙以九二納婦而六三取女則不利，節以初九不出而九二不出則失時，得失是非不可不辨也。噫重卦六爻之意，亦要諸吉凶存亡之辭而巳。有同位而異物，同物而異象，同象而異辭，要諸辭則四者不同，居然易見，可指掌而知矣。六爻者、變動相錯而有吉凶存亡者也。彖辭者、合內外二體。以一爻相變而有者也。知者明於理、則觀諸彖辭，而爻義已知其過半矣。</p><p>二與四同功而異位、其善不同。二多譽、四多懼、近也。柔之為道、不利遠者、其要無咎、其用柔中也。三與五同功而異位，三多兇，五多功，貴賤之等也。其柔危，其剛勝邪？龔氏合易之為書也為一章，誤矣。今從故本。此章再明中爻之義。二四耦也，同為陰之功，內外異位，有不同焉。二多譽，四多懼，何也？四近五，五尊位，近尊位則多懼。月望日則食，禮近君則屈。然柔之為道不利。遠者，坤從乾也。二遠於五，所以多譽者，其要在於雖柔而無咎，以其用柔中也。用柔而失中，其能無咎乎？三、五奇也，同為陽之功，內外異位，有不同焉。三多兇，五多功，何也？五貴三賤，其等不同也。三處下位之極，其柔居之，則危不勝任矣。其剛居之，將以為勝邪？以剛居剛，有時乎過剛矣。危則疾顛，過則易敗，此三所以多兇也。若五不然，以剛居之，得尊位大中，宜處貴者也。以柔居之，有處謙執柔以貴下賤之美，二為五用矣，此五所以多功也。夫二、五，中也，二、三、四、五皆曰中爻，何也？曰：以三數之，自一至三，以二為中；自四至上，以五為中。以五數之，自二至上，以四為中；以四數之，自二至五，以三四為中。復之九四曰中行，獨復中孚，以二柔在內名卦。卦言德，爻言善者，積善成德也。</p><p>易之為書也，廣大悉備，有天道焉，有人道焉，有地道焉。兼三材而兩之，故六。六者非它也，三材之道也。道有變動，故曰爻；爻有等，故曰物。物相雜，故曰文。文不當，故吉凶生焉。易之興也，其當殷之末世，周之盛德耶？當文王與紂之事邪？是故其辭危，危者使平，易者使傾。其道甚大，百物不廢，懼以終始，其要無咎，此之謂易之道也。此章再明六爻雜物之義。易之為書，廣大而無外，語天地之間，則無乎不備矣。有天道焉，陰與陽也。有人道焉，仁與義也。有地道焉，柔與剛也。此三者一物而兩體。陰陽也，而謂之天；仁義也，而謂之人。剛柔也而謂之地，故曰三材。兼三材而兩之，故六。兼之者，天之道兼陰與陽也，人之道兼仁與義也，地之道兼柔與剛也。六者非它，即三材之道也。是故三畫而有重卦，六即三也，三即一也。道有變，易有流動，爻則傚之，故曰爻。天地相函，精氣所聚，其等有六，曰物。八物相錯而成文，故曰文。文當其位則吉，文不當其位則兇，故吉凶生焉。易之興也，當殷之末，世周之盛德邪？何系之辭而告其吉凶者如是乎？又紂與文王之事邪？何君子處小人之間而其辭危乎？是故危懼者使知可平，慢易者使知必傾。所以長君子消小人也。其道甚大。君子小人無所不容。不容則不足以準天地百物不廢者。所以形容其道。所謂悉備也。初辭擬之。卒成之終。使知善不善之積。成名滅身。非一朝夕之漸。故原始要終而懼焉。其大要歸之無咎而巳。此之謂易之道。易之道，立人道以貫天地而為一者也。</p><p>夫乾，天下之至健也，德行恆，易以知險。</p><p>夫坤，天下之至順也，德行恆簡以知阻。能說諸心，能研諸侯之慮，定天下之吉凶，成天下之亹亹者。是故變化云為，吉事有祥，象事知器，佔事知來。天地設位，聖人成能。人謀鬼謀，百姓與能。八卦以象告，爻彖以情言。剛柔雜居，而吉凶可見矣。變動以利言，吉凶以情遷。是故愛惡相攻而吉凶生、遠近相取而悔吝生。情偽相感而利害生。凡易之情，近而不相得則兇。或害之，悔且吝。將叛者。其辭慚。中心疑者其辭枝。吉人之辭寡、躁人之辭多。誣善之人其辭遊、失其守者其辭屈。</p><p>此章論六爻而歸之於簡易。乾健而為萬物先、莫或御之、故其德行恆易。坤順以從乾、無二適也、故其德行恆簡、以易也、故知險之為難。以簡也、故知阻之可疑。簡生於易、阻生於險。簡易也，故能說諸心；知險阻也，故能研諸慮。簡易者，我心之所固有，反而得之，能無說乎？以我所有，慮其不然，反覆不捨，能無研乎？曰研諸侯之慮者，衍侯之二字。王弼略例曰：能研諸慮，則衍文可知。天下之吉凶，藏於無形，至難定也。天下之亹亹，來而不巳，至難成也。定之成之者，簡易而巳。乾坤變化，有云有為。雲者，言也；為者，動也。吉事有祥，祥者，吉之先見，有祥，必先知之，兼言動也。制器者尚象，知器則知成器之為天下利而可動也。卜筮者尚佔，知來則知來物而言動審矣，是以能定天下之吉凶，成天下之亹亹，非知險知阻者能之乎？天尊地卑，乾坤設位，聖人配天地而立，合乾坤之德以成能事。能說諸心，能研諸慮者，明以盡人謀也。定天下之吉凶，成天下之亹亹者，幽以盡鬼謀也。人謀鬼謀，幽顯合一，天下樂推而不厭。百姓之愚、與之以能矣。成能故也。伏羲氏始畫八卦、不言而告之以象者、至簡易也。後世聖人演之為六十四卦、有爻有彖、以人情變動言之、於辭知險阻也。且八卦成列、剛柔雜居、吉凶巳可見矣。然道有變動。變則通。通則其用不窮、所以盡利者，不可不言也。故變動以利言，吉凶以情而遷，巧曆之所不能計也。聖人唯恐遷之而失其正矣，故爻彖以情言。變動者何？情偽之所為也。人之情偽難知矣，以情相感則利生，以偽相感則害生。近不必取，遠不必舍，則悔吝生。愛惡不一起而相攻，則吉凶生。吉凶生而悔吝著，情偽其能掩乎？是則情偽相感也，遠近相取也，愛惡相攻也，爻有變動也。有利害斯有悔吝，有悔吝斯有吉凶，吉凶以情遷也。悔吝者何？凡易之情，陰陽相求，內外相應，近而不相得，則偽不可久。物或害之，害之則兇將至矣。悔吝者，利害吉凶之界乎。害之而悔，則吉且利矣。吝而不悔則兇，聖人不得不以利言之，而使之遠害也。故曰聖人之情見乎辭。然則何以知情偽邪？考其辭可矣。將叛者，其心慚負，故其辭愧；中心疑者，其心惑亂，故其辭枝。吉人守約，故其辭寡。躁人慾速，故其辭多。誣善之人妄，故其辭遊。失其守者窮，故其辭屈。吉人辭寡，以簡易知也。五者反是，以知險知阻而知也。簡易則吉，險阻則兇。其辭雖六，其別則二，情偽而巳矣。上系言易簡而天下之理得，下系終之以易簡而知險阻，故曰殊塗而同歸，一致而百慮。周易繫辭下傳第八。</p>',21)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
